// Generates the TypeScript view of src/contracts/protocol.json.
// Usage: node scripts/generate-contracts.mjs [--check]
//   --check  fails if the generated file is out of date (used in CI).
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { compile } from "json-schema-to-typescript";

const root = join(import.meta.dirname, "..");
const protocolPath = join(root, "src", "contracts", "protocol.json");
const outputPath = join(root, "src", "ui", "src", "bridge", "generated", "protocol.ts");
const protocol = JSON.parse(readFileSync(protocolPath, "utf8"));

const pascal = (name) =>
  name
    .split(/[._-]/)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("");

// Every named type becomes a definition, so json-schema-to-typescript emits it.
const definitions = {};
const aliases = [];
const methodLines = [];

// A payload that is only a reference to a shared definition becomes a type alias;
// compiling it as its own schema would emit a duplicate interface.
const refName = (schema) => {
  const keys = Object.keys(schema);
  return keys.length === 1 && typeof schema.$ref === "string" && schema.$ref.startsWith("#/$defs/")
    ? schema.$ref.slice("#/$defs/".length)
    : undefined;
};

const declare = (name, schema) => {
  const target = refName(schema);
  if (target) aliases.push(`export type ${name} = ${target};`);
  else definitions[name] = schema;
};
const notificationLines = [];

for (const [name, definition] of Object.entries(protocol.$defs)) {
  definitions[name] = definition;
}

for (const [method, { params, result }] of Object.entries(protocol.methods)) {
  const base = pascal(method);
  let paramsType = "undefined";
  if (params !== null) {
    paramsType = `${base}Params`;
    declare(paramsType, params);
  }
  declare(`${base}Result`, result);
  methodLines.push(`  "${method}": { params: ${paramsType}; result: ${base}Result };`);
}

for (const [notification, { params }] of Object.entries(protocol.notifications)) {
  const type = `${pascal(notification)}Notification`;
  declare(type, params);
  notificationLines.push(`  "${notification}": ${type};`);
}

// Titles drive the generated type names.
for (const [name, schema] of Object.entries(definitions)) {
  definitions[name] = { ...schema, title: name };
}

const types = await compile(
  { title: "Protocol", $defs: definitions, type: "object", additionalProperties: false },
  "Protocol",
  {
    bannerComment: "",
    unreachableDefinitions: true,
    format: false,
    strictIndexSignatures: true,
    // A list with at most N items stays a plain array: the core checks the limit against the contract.
    ignoreMinAndMaxItems: true,
  },
);

// Drop the synthetic root type and the generator's boilerplate comments.
const boilerplate = / \*( \n|\n) \* This interface was referenced by `Protocol`'s JSON-Schema\n \* via the `definition` "\w+"\.\n/g;
const namedTypes = types
  .replace(/\r\n/g, "\n")
  .replace(/export interface Protocol \{\s*\}\s*/, "")
  .replace(boilerplate, "")
  .replace(/ \* This interface was referenced by `Protocol`'s JSON-Schema\n \* via the `definition` "\w+"\.\n/g, "")
  .replace(/\/\*\*\n \*\/\n/g, "")
  .trim();

const output = `// Generated by scripts/generate-contracts.mjs from src/contracts/protocol.json.
// Do not edit by hand: change the contract and run \`npm run contracts:generate\`.

export const PROTOCOL_VERSION = ${protocol.protocolVersion} as const;

export const ErrorCodes = ${JSON.stringify(protocol.errorCodes, null, 2)} as const;

${namedTypes}

${aliases.join("\n")}

/** Every request the core understands, with its params and result types. */
export interface CoreMethods {
${methodLines.join("\n")}
}

/** Every notification the core broadcasts, with its payload type. */
export interface CoreNotifications {
${notificationLines.join("\n")}
}
`;

const prettier = await import("prettier");
const config = (await prettier.resolveConfig(outputPath)) ?? {};
const formatted = await prettier.format(output, { ...config, parser: "typescript" });

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(outputPath, "utf8");
  } catch {
    // Missing file counts as out of date.
  }
  if (current !== formatted) {
    console.error("protocol.ts is out of date. Run `npm run contracts:generate`.");
    process.exit(1);
  }
  console.log("protocol.ts is up to date");
} else {
  mkdirSync(dirname(outputPath), { recursive: true });
  writeFileSync(outputPath, formatted);
  console.log(`generated ${outputPath}`);
}
